// @FIGURE_CODE_BEGIN
(function () {
  var NAVY = '#1F3864';
  var DOT = '#12203a';
  var W = 520, H = 420, OX = 182, OY = 252, U = 32;

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);
  draw.rect(W, H).fill('#ffffff');

  var state = { theta: 55, r: 3, mode: 'Both' };
  var lastOp = { rect: 1, polar: 1 };

  /* ---------- helpers ---------- */
  function pts(arr) { return arr.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' '); }

  function arrowHead(g, x, y, dx, dy, size, halfw, color) {
    var L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
    var nx = -dy, ny = dx;
    g.polygon(pts([
      [x, y],
      [x - dx * size + nx * halfw, y - dy * size + ny * halfw],
      [x - dx * size - nx * halfw, y - dy * size - ny * halfw]
    ])).fill(color).stroke('none');
  }

  function arcPath(cx, cy, R, a0, a1) {
    var x0 = cx + R * Math.cos(a0), y0 = cy - R * Math.sin(a0);
    var x1 = cx + R * Math.cos(a1), y1 = cy - R * Math.sin(a1);
    var large = Math.abs(a1 - a0) > Math.PI ? 1 : 0;
    var sweep = (a1 > a0) ? 0 : 1;
    return 'M' + x0.toFixed(2) + ' ' + y0.toFixed(2) + ' A' + R.toFixed(2) + ' ' + R.toFixed(2) +
      ' 0 ' + large + ' ' + sweep + ' ' + x1.toFixed(2) + ' ' + y1.toFixed(2);
  }

  function mkText(g, txt, x, y, o) {
    o = o || {};
    var t = g.plain(txt);
    t.font({
      family: o.family || 'Georgia, "Times New Roman", serif',
      size: o.size || 17,
      style: o.style || 'italic',
      weight: o.weight || 'normal'
    });
    t.attr({
      x: x, y: y,
      'text-anchor': o.anchor || 'middle',
      'dominant-baseline': 'central',
      fill: o.fill || NAVY
    });
    if (o.halo !== false) {
      t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.haloW || 3.5, 'stroke-linejoin': 'round' });
    }
    return t;
  }

