// @FIGURE_CODE_BEGIN
(function () {
  var NAVY = '#1F3864';
  var DOT = '#12203a';
  var W = 520, H = 420, OX = 182, OY = 252, U = 32;

  var draw = SVG().addTo(document.getElementById('container')).size('100%', '100%');
  draw.viewbox(0, 0, W, H);
  draw.rect(W, H).fill('#ffffff');

  var state = { theta: 55, r: 3, mode: 'Both' };
  var lastOp = { rect: 1, polar: 1 };

  /* ---------- helpers ---------- */
  function pts(arr) { return arr.map(function (p) { return p[0].toFixed(2) + ',' + p[1].toFixed(2); }).join(' '); }

  function arrowHead(g, x, y, dx, dy, size, halfw, color) {
    var L = Math.hypot(dx, dy) || 1; dx /= L; dy /= L;
    var nx = -dy, ny = dx;
    g.polygon(pts([
      [x, y],
      [x - dx * size + nx * halfw, y - dy * size + ny * halfw],
      [x - dx * size - nx * halfw, y - dy * size - ny * halfw]
    ])).fill(color).stroke('none');
  }

  function arcPath(cx, cy, R, a0, a1) {
    var x0 = cx + R * Math.cos(a0), y0 = cy - R * Math.sin(a0);
    var x1 = cx + R * Math.cos(a1), y1 = cy - R * Math.sin(a1);
    var large = Math.abs(a1 - a0) > Math.PI ? 1 : 0;
    var sweep = (a1 > a0) ? 0 : 1;
    return 'M' + x0.toFixed(2) + ' ' + y0.toFixed(2) + ' A' + R.toFixed(2) + ' ' + R.toFixed(2) +
      ' 0 ' + large + ' ' + sweep + ' ' + x1.toFixed(2) + ' ' + y1.toFixed(2);
  }

  function mkText(g, txt, x, y, o) {
    o = o || {};
    var t = g.plain(txt);
    t.font({
      family: o.family || 'Georgia, "Times New Roman", serif',
      size: o.size || 17,
      style: o.style || 'italic',
      weight: o.weight || 'normal'
    });
    t.attr({
      x: x, y: y,
      'text-anchor': o.anchor || 'middle',
      'dominant-baseline': 'central',
      fill: o.fill || NAVY
    });
    if (o.halo !== false) {
      t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': o.haloW || 3.5, 'stroke-linejoin': 'round' });
    }
    return t;
  }

  function interactive(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip(), e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function () { showPopup(title, body()); });
    return el;
  }

  function f2(v) { var s = (Math.abs(v) < 0.005) ? 0 : v; return s.toFixed(2); }

  /* ---------- static layer: axes ---------- */
  var stat = draw.group();

  // Real axis
  stat.line(26, OY, 452, OY).stroke({ color: '#000', width: 1.6 });
  arrowHead(stat, 458, OY, 1, 0, 12, 4.5, '#000');
  arrowHead(stat, 20, OY, -1, 0, 12, 4.5, '#000');
  mkText(stat, 'Real', 468, OY + 1, {
    family: 'Helvetica, Arial, sans-serif', size: 15, style: 'italic',
    weight: 'bold', fill: '#000', anchor: 'start', halo: false
  });

  // Imaginary axis
  stat.line(OX, 406, OX, 44).stroke({ color: '#000', width: 1.6 });
  arrowHead(stat, OX, 38, 0, -1, 12, 4.5, '#000');
  arrowHead(stat, OX, 412, 0, 1, 12, 4.5, '#000');
  mkText(stat, 'Imaginary', OX + 6, 24, {
    family: 'Helvetica, Arial, sans-serif', size: 15, style: 'italic',
    weight: 'bold', fill: '#000', anchor: 'middle', halo: false
  });

  // origin marker
  stat.circle(4).center(OX, OY).fill('#000');

  var dyn = draw.group();

  /* ---------- emphasis ---------- */
  function ops(mode) {
    if (mode === 'Rectangular (x, y)') return { rect: 1, polar: 0.45 };
    if (mode === 'Polar (r, θ)') return { rect: 0.45, polar: 1 };
    return { rect: 1, polar: 1 };
  }

  /* ---------- render ---------- */
  function render(animate) {
    dyn.clear();

    var th = state.theta * Math.PI / 180;
    var R = state.r * U;
    var wx = state.r * Math.cos(th), wy = state.r * Math.sin(th);
    var px = OX + R * Math.cos(th), py = OY - R * Math.sin(th);
    var op = ops(state.mode);

    var gPolar = dyn.group();   // arc, hypotenuse, angle arc, r & θ labels
    var gRect = dyn.group();    // legs, right-angle marker, x & y labels
    var gTop = dyn.group();     // dot, point label, readout

    /* --- heavy circular arc through the point --- */
    var a0 = th - 75 * Math.PI / 180, a1 = th + 58 * Math.PI / 180;
    var arc = gPolar.path(arcPath(OX, OY, R, a0, a1))
      .fill('none')
      .stroke({ color: NAVY, width: 4, linecap: 'round' });
    arrowHead(gPolar, OX + R * Math.cos(a1), OY - R * Math.sin(a1),
      -Math.sin(a1), -Math.cos(a1), 15, 6.5, NAVY);
    arrowHead(gPolar, OX + R * Math.cos(a0), OY - R * Math.sin(a0),
      Math.sin(a0), Math.cos(a0), 15, 6.5, NAVY);
    interactive(arc,
      function () { return 'Circle of radius r = ' + f2(state.r); },
      'The circle of constant modulus',
      function () {
        return 'Every point on this circle is exactly r = ' + f2(state.r) + ' units from the origin, so they all share the same modulus. Changing θ slides the point along the circle; changing r inflates or shrinks the circle itself.';
      });

    /* --- hypotenuse --- */
    var hyp = gPolar.line(OX, OY, px, py).stroke({ color: NAVY, width: 2.2, linecap: 'round' });
    interactive(hyp,
      function () { return 'r = ' + f2(state.r); },
      'r — the modulus',
      function () {
        return 'The hypotenuse of the right triangle is the distance from the origin to the point: r = √(x² + y²) = √(' + f2(wx) + '² + ' + f2(wy) + '²) = ' + f2(state.r) + '. It is not extra information — it is a side of the same triangle whose legs are x and y.';
      });

    /* --- angle arc at origin --- */
    if (state.theta > 6 && state.theta < 354) {
      var aArc = gPolar.path(arcPath(OX, OY, 30, 0, th))
        .fill('none').stroke({ color: NAVY, width: 1.6 });
      interactive(aArc,
        function () { return 'θ = ' + Math.round(state.theta) + '°'; },
        'θ — the direction angle',
        function () {
          return 'θ is measured counterclockwise from the positive real axis to the hypotenuse. It is the base angle of the triangle, so cos θ = x / r and sin θ = y / r.';
        });
      var hm = th / 2;
      mkText(gPolar, 'θ', OX + 48 * Math.cos(hm), OY - 48 * Math.sin(hm), { size: 17 });
    }

    /* --- r label, perpendicular to hypotenuse on the outside --- */
    var mx = OX + (px - OX) / 2, my = OY + (py - OY) / 2;
    var nx = -Math.sin(th), ny = -Math.cos(th);
    // choose the normal pointing away from the foot of the perpendicular
    if ((px - mx) * nx + (OY - my) * ny > 0) { nx = -nx; ny = -ny; }
    mkText(gPolar, 'r', mx + nx * 19, my + ny * 19, { size: 18 });

    /* --- legs --- */
    var legY = gRect.line(px, py, px, OY).stroke({ color: NAVY, width: 2.2, linecap: 'round' });
    var legX = gRect.line(OX, OY, px, OY).stroke({ color: NAVY, width: 2.2, linecap: 'round' });
    interactive(legY,
      function () { return 'y = r sin θ = ' + f2(wy); },
      'y — the imaginary part',
      function () {
        return 'The vertical leg measures the imaginary part: y = r sin θ = ' + f2(state.r) + ' · sin ' + Math.round(state.theta) + '° = ' + f2(wy) + '. It becomes negative once the point drops below the real axis.';
      });
    interactive(legX,
      function () { return 'x = r cos θ = ' + f2(wx); },
      'x — the real part',
      function () {
        return 'The horizontal leg measures the real part: x = r cos θ = ' + f2(state.r) + ' · cos ' + Math.round(state.theta) + '° = ' + f2(wx) + '. It becomes negative to the left of the imaginary axis.';
      });

    /* --- right-angle marker --- */
    if (Math.abs(px - OX) > 14 && Math.abs(py - OY) > 14) {
      var sx = (px > OX) ? -1 : 1, sy = (py < OY) ? -1 : 1, s = 9;
      gRect.path('M' + (px + sx * s) + ' ' + OY + ' L' + (px + sx * s) + ' ' + (OY + sy * s) +
        ' L' + px + ' ' + (OY + sy * s))
        .fill('none').stroke({ color: NAVY, width: 1.1, opacity: 0.75 });
    }

    /* --- x and y labels --- */
    if (Math.abs(py - OY) > 26) {
      var sgnX = (Math.cos(th) >= 0) ? 1 : -1;
      mkText(gRect, 'y', px + sgnX * 16, (py + OY) / 2, { size: 17 });
    }
    if (Math.abs(px - OX) > 34) {
      var sgnY = (Math.sin(th) >= 0) ? 1 : -1;
      mkText(gRect, 'x', (OX + px) / 2, OY + sgnY * 20, { size: 17 });
    }

    /* --- the point --- */
    var dot = gTop.circle(12).center(px, py).fill(DOT);
    interactive(dot,
      function () { return f2(wx) + ' + ' + f2(wy) + 'i   =   ' + f2(state.r) + '∠' + Math.round(state.theta) + '°'; },
      'Two names, one point',
      function () {
        return 'This single location can be named by its rectangular coordinates, x + yi = ' + f2(wx) + ' + ' + f2(wy) + 'i, or by its polar pair, r(cos θ + i sin θ) = ' + f2(state.r) + '(cos ' + Math.round(state.theta) + '° + i sin ' + Math.round(state.theta) + '°). The right triangle is the dictionary: x = r cos θ, y = r sin θ, r = √(x² + y²).';
      });

