    lx = Math.max(44, Math.min(W - 44, lx)); ly = Math.max(16, Math.min(H - 14, ly));
    mkText(gTop, 'x + yi', lx, ly, { size: 17, haloW: 4.5 });

    /* --- readout panel --- */
    var pr = gTop.group();
    pr.rect(196, 88).move(316, 16).fill('#ffffff').opacity(0.88)
      .stroke({ color: '#e1e5ea', width: 1 });
    var lines = [
      'x = ' + f2(wx) + '     y = ' + f2(wy),
      'r = ' + f2(state.r) + '     θ = ' + Math.round(state.theta) + '°',
      'x + yi = ' + f2(wx) + ' + ' + f2(wy) + 'i',
      'r(cos θ + i sin θ)',
      '= ' + f2(state.r) + '(cos ' + Math.round(state.theta) + '° + i sin ' + Math.round(state.theta) + '°)'
    ];
    for (var i = 0; i < lines.length; i++) {
      mkText(pr, lines[i], 504, 30 + i * 15, {
        family: 'Helvetica, Arial, sans-serif', size: 11.5, style: 'normal',
        anchor: 'end', fill: (i < 2 ? '#333' : NAVY), halo: false
      });
