      gRect.opacity(lastOp.rect); gRect.animate(280).opacity(op.rect);
      gPolar.opacity(lastOp.polar); gPolar.animate(280).opacity(op.polar);
    } else {
      gRect.opacity(op.rect);
      gPolar.opacity(op.polar);
    }
