  function arcPath(cx, cy, R, a0, a1) {
    var x0 = cx + R * Math.cos(a0), y0 = cy - R * Math.sin(a0);
    var x1 = cx + R * Math.cos(a1), y1 = cy - R * Math.sin(a1);
    var large = Math.abs(a1 - a0) > Math.PI ? 1 : 0;
    var sweep = (a1 > a0) ? 0 : 1;
    return 'M' + x0.toFixed(2) + ' ' + y0.toFixed(2) + ' A' + R.toFixed(2) + ' ' + R.toFixed(2) +
      ' 0 ' + large + ' ' + sweep + ' ' + x1.toFixed(2) + ' ' + y1.toFixed(2);
  }

  function mkText(g, txt, x, y, o) {
    o = o || {};
    var t = g.plain(txt);
    t.font({
      family: o.family || 'Georgia, "Times New Roman", serif',
      size: o.size || 18,
      style: o.style || 'italic',
      weight: o.weight || 'normal'
    });
    t.attr({
      x: x, y: y,
      'text-anchor': o.anchor || 'middle',
      'dominant-baseline': 'central',
      fill: o.fill || NAVY
    });
    if (o.halo !== false) {
      t.attr({
        'paint-order': 'stroke', stroke: '#fff',
        'stroke-width': o.haloW || 3.5, 'stroke-linejoin': 'round'
      });
    }
    return t;
  }

  function interactive(el, tip, title, body) {
    el.css('cursor', 'pointer');
    el.on('mousemove', function (e) { showTooltip(tip(), e); });
    el.on('mouseleave', function () { hideTooltip(); });
    el.on('click', function () { showPopup(title, body()); });
    return el;
  }

  function f2(v) { var s = (Math.abs(v) < 0.005) ? 0 : v; return s.toFixed(2); }

  /* the heavy circle arc: always crosses the axis just beyond the point on
     each side, so it reads as a full circle being traced (as in the source) */
  function arcRange(thDeg) {
    var up = Math.ceil((thDeg + 0.0001) / 90) * 90;
    var dn = Math.floor((thDeg - 0.0001) / 90) * 90;
    var a1 = Math.min(Math.max(thDeg + 45, up + 13), thDeg + 118);
    var a0 = Math.max(Math.min(thDeg - 45, dn - 13), thDeg - 118);
    return [a0 * RAD, a1 * RAD];
  }

  /* ---------- static layer: axes ---------- */
  var stat = draw.group();

  stat.line(34, OY, 464, OY).stroke({ color: '#000', width: 1.6 });
  arrowHead(stat, 470, OY, 1, 0, 13, 5, '#000');
  arrowHead(stat, 28, OY, -1, 0, 13, 5, '#000');
  mkText(stat, 'Real', 482, OY + 1, {
    family: 'Helvetica, Arial, sans-serif', size: 16, style: 'italic',
    weight: 'bold', fill: '#000', anchor: 'start', halo: false
  });

  stat.line(OX, 398, OX, 44).stroke({ color: '#000', width: 1.6 });
  arrowHead(stat, OX, 38, 0, -1, 13, 5, '#000');
  arrowHead(stat, OX, 404, 0, 1, 13, 5, '#000');
  mkText(stat, 'Imaginary', OX, 20, {
    family: 'Helvetica, Arial, sans-serif', size: 16, style: 'italic',
    weight: 'bold', fill: '#000', anchor: 'middle', halo: false
  });

  var dyn = draw.group();

  /* annotation emphasis — only the LABELS fade, the geometry never dims */
  function ops(mode) {
    if (mode === 'Rectangular (x, y)') return { rect: 1, polar: 0.14 };
    if (mode === 'Polar (r, θ)') return { rect: 0.14, polar: 1 };
    return { rect: 1, polar: 1 };
  }

  /* ---------- render ---------- */
  function render(animate) {
    dyn.clear();

    var th = state.theta * RAD;
    var R = state.r * U;
    var wx = state.r * Math.cos(th), wy = state.r * Math.sin(th);
    var px = OX + R * Math.cos(th), py = OY - R * Math.sin(th);
    var op = ops(state.mode);

    var gGeom = dyn.group();      // always full-strength navy
    var gPolarLbl = dyn.group();  // r, θ annotations
    var gRectLbl = dyn.group();   // x, y annotations
    var gTop = dyn.group();       // dot + point label

    /* --- heavy circular arc of radius r --- */
    var rg = arcRange(state.theta), a0 = rg[0], a1 = rg[1];
    var arc = gGeom.path(arcPath(OX, OY, R, a0, a1))
      .fill('none')
      .stroke({ color: NAVY, width: 4.2, linecap: 'butt' });
    arrowHead(gGeom, OX + R * Math.cos(a1), OY - R * Math.sin(a1),
      -Math.sin(a1), -Math.cos(a1), 16, 7, NAVY);
    arrowHead(gGeom, OX + R * Math.cos(a0), OY - R * Math.sin(a0),
      Math.sin(a0), Math.cos(a0), 16, 7, NAVY);
    interactive(arc,
      function () { return 'Circle of radius r = ' + f2(state.r); },
      'The circle of constant modulus',
      function () {
        return 'Every point on this circle is exactly r = ' + f2(state.r) +
          ' units from the origin, so they all share the same modulus. Changing θ slides the point along the circle; changing r inflates or shrinks the circle itself.';
      });

    /* --- hypotenuse --- */
    var hyp = gGeom.line(OX, OY, px, py).stroke({ color: NAVY, width: 2.4, linecap: 'round' });
    interactive(hyp,
      function () { return 'r = ' + f2(state.r); },
      'r — the modulus',
      function () {
        return 'The hypotenuse of the right triangle is the distance from the origin to the point: r = √(x² + y²) = √(' +
          f2(wx) + '² + ' + f2(wy) + '²) = ' + f2(state.r) +
          '. It is not extra information — it is a side of the same triangle whose legs are x and y.';
      });

    /* --- legs --- */
    var legY = gGeom.line(px, py, px, OY).stroke({ color: NAVY, width: 2.4, linecap: 'round' });
    var legX = gGeom.line(OX, OY, px, OY).stroke({ color: NAVY, width: 2.4, linecap: 'round' });
    interactive(legY,
      function () { return 'y = r sin θ = ' + f2(wy); },
      'y — the imaginary part',
      function () {
        return 'The vertical leg measures the imaginary part: y = r sin θ = ' + f2(state.r) +
          ' · sin ' + Math.round(state.theta) + '° = ' + f2(wy) +
          '. It becomes negative once the point drops below the real axis.';
      });
    interactive(legX,
      function () { return 'x = r cos θ = ' + f2(wx); },
      'x — the real part',
      function () {
        return 'The horizontal leg measures the real part: x = r cos θ = ' + f2(state.r) +
          ' · cos ' + Math.round(state.theta) + '° = ' + f2(wx) +
          '. It becomes negative to the left of the imaginary axis.';
      });

    /* --- faint right-angle marker --- */
    if (Math.abs(px - OX) > 16 && Math.abs(py - OY) > 16) {
      var sx = (px > OX) ? -1 : 1, sy = (py < OY) ? -1 : 1, s = 9;
      gGeom.path('M' + (px + sx * s) + ' ' + OY + ' L' + (px + sx * s) + ' ' + (OY + sy * s) +
        ' L' + px + ' ' + (OY + sy * s))
        .fill('none').stroke({ color: NAVY, width: 1, opacity: 0.35 });
    }

    /* --- angle arc + θ label (polar annotation) --- */
    if (state.theta > 6 && state.theta < 354) {
      var aArc = gPolarLbl.path(arcPath(OX, OY, 36, 0, th))
        .fill('none').stroke({ color: NAVY, width: 1.5 });
      interactive(aArc,
        function () { return 'θ = ' + Math.round(state.theta) + '°'; },
        'θ — the direction angle',
        function () {
          return 'θ is measured counterclockwise from the positive real axis to the hypotenuse. It is the base angle of the triangle, so cos θ = x / r and sin θ = y / r.';
        });
      var hm = th / 2;
      mkText(gPolarLbl, 'θ', OX + 54 * Math.cos(hm), OY - 54 * Math.sin(hm), { size: 18 });
    }

    /* --- r label: midpoint of hypotenuse, offset to the outside --- */
    var mx = OX + (px - OX) / 2, my = OY + (py - OY) / 2;
    var c = Math.cos(th), sn = Math.sin(th);
    var nx = -sn, ny = -c;
    if (nx * c + ny * sn > 0) { nx = -nx; ny = -ny; }   // point away from the foot
    mkText(gPolarLbl, 'r', mx + nx * 21, my + ny * 21, { size: 19 });

    /* --- x and y labels --- */
    if (Math.abs(py - OY) > 28) {
      var sgnX = (c >= 0) ? 1 : -1;
      mkText(gRectLbl, 'y', px + sgnX * 17, (py + OY) / 2, { size: 18 });
    }
    if (Math.abs(px - OX) > 36) {
      var sgnY = (sn >= 0) ? 1 : -1;
      mkText(gRectLbl, 'x', (OX + px) / 2, OY + sgnY * 21, { size: 18 });
    }

    /* --- the point --- */
    var dot = gTop.circle(12).center(px, py).fill(DOT);
    interactive(dot,
      function () {
        return f2(wx) + ' + ' + f2(wy) + 'i   =   ' + f2(state.r) + '∠' + Math.round(state.theta) + '°';
      },
      'Two names, one point',
      function () {
        return 'This single location can be named by its rectangular coordinates, x + yi = ' +
          f2(wx) + ' + ' + f2(wy) + 'i, or by its polar pair, r(cos θ + i sin θ) = ' +
          f2(state.r) + '(cos ' + Math.round(state.theta) + '° + i sin ' + Math.round(state.theta) +
          '°). The right triangle is the dictionary: x = r cos θ, y = r sin θ, r = √(x² + y²).';
      });

    /* --- 'x + yi' label, just up-and-right of the dot (as in the source) --- */
    var anchor = 'start', lx = px + 11, ly = py - 23;
    if (lx > W - 96) { anchor = 'end'; lx = px - 11; }
    ly = Math.max(16, Math.min(H - 14, ly));
    mkText(gTop, 'x + yi', lx, ly, { size: 18, anchor: anchor, haloW: 4.5 });

    /* --- label fade only (geometry keeps full navy) --- */
    if (animate && (lastOp.rect !== op.rect || lastOp.polar !== op.polar)) {
      gRectLbl.opacity(lastOp.rect); gRectLbl.animate(280).opacity(op.rect);
      gPolarLbl.opacity(lastOp.polar); gPolarLbl.animate(280).opacity(op.polar);
    } else {
      gRectLbl.opacity(op.rect);
      gPolarLbl.opacity(op.polar);
    }
    lastOp = op;

    updateReadout(wx, wy);
  }

  /* ---------- readout lives in the side panel, not on the canvas ---------- */
  function updateReadout(wx, wy) {
    var el = document.getElementById('readout');
    if (!el) return;
    var d = Math.round(state.theta);
    el.innerHTML =
      'x = ' + f2(wx) + '&nbsp;&nbsp; y = ' + f2(wy) + '<br>' +
      'r = ' + f2(state.r) + '&nbsp;&nbsp; θ = ' + d + '°<br>' +
      'x + yi = ' + f2(wx) + ' + ' + f2(wy) + 'i<br>' +
      'r(cos θ + i sin θ)<br>' +
      '&nbsp;= ' + f2(state.r) + '(cos ' + d + '° + i sin ' + d + '°)';
  }

  /* ---------- controls ---------- */
  window.update_theta = function (v) { state.theta = v; render(false); };
  window.update_modulus = function (v) { state.r = v; render(false); };
  window.toggle_labelMode = function (val) { state.mode = val; render(true); };

  /* ---------- demo steps ---------- */
  var steps = [
    {
      title: 'The point and its triangle',
      narration: 'A complex number x + yi is plotted as a point in the plane, with the real part measured along the horizontal axis and the imaginary part along the vertical axis. Dropping a perpendicular to the real axis forms a right triangle whose legs are exactly x and y.',
      state: { theta: 55, modulus: 3, labelMode: 'Both' }
    },
    {
      title: 'Naming the hypotenuse and the angle',
      narration: 'The hypotenuse from the origin is the modulus r, and the angle it makes with the positive real axis is θ. These two numbers locate the point just as completely as x and y do.',
      state: { theta: 55, modulus: 3, labelMode: 'Polar (r, θ)' }
    },
    {
      title: 'Sweep θ around the circle',
      narration: 'Drag θ and the point rides the heavy circular arc: r never changes, but x = r cos θ and y = r sin θ stretch, shrink, and change sign as the point moves through each quadrant.',
      state: { theta: 145, modulus: 3, labelMode: 'Rectangular (x, y)' }
    },
    {
      title: 'Change r, keep the direction',
      narration: 'Now hold θ fixed and grow r. The circle and the hypotenuse expand together and both legs scale by the same factor — r really is distance from the origin, not an extra label.',
      state: { theta: 145, modulus: 4.5, labelMode: 'Both' }
    },
    {
      title: 'Two names, one point',
      narration: 'Switch the annotations back and forth: the dot never moves, yet it reads as x + yi in rectangular form and r(cos θ + i sin θ) in polar form. The triangle is the dictionary between them.',
      state: { theta: 55, modulus: 3, labelMode: 'Both' }
    }
  ];
  var cur = 0;

  function goStep(i, animate) {
    cur = (i + steps.length) % steps.length;
    var s = steps[cur];
    document.getElementById('thetaInput').value = s.state.theta;
    document.getElementById('thetaVal').value = s.state.theta;
    document.getElementById('modulusInput').value = s.state.modulus;
    document.getElementById('modulusVal').value = (+s.state.modulus).toFixed(1);
    document.getElementById('labelModeInput').value = s.state.labelMode;
    state.theta = s.state.theta;
    state.r = s.state.modulus;
    state.mode = s.state.labelMode;
    document.getElementById('demoNarration').innerHTML =
      '<b>' + s.title + '</b><br>' + s.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
    render(animate);
  }
  window.nextStep = function () { goStep(cur + 1, true); };
  window.prevStep = function () { goStep(cur - 1, true); };

  goStep(0, false);
  window.__markRendered();
})();
// @FIGURE_CODE_END

